/** One generated Codex role file definition. */
export interface CaaraCodexRoleDefinition {
  readonly description: string;
  readonly developerInstructions: string;
  readonly model: string;
  readonly name: string;
}

/** One installable external driver catalog for generated Codex roles. */
export interface CaaraCodexRoleDriverCatalog {
  readonly driverName: string;
  readonly executableName: string;
  readonly roles: readonly CaaraCodexRoleDefinition[];
}

