/** Installed role catalogs owned by Caara. */
export const safeCodexRoleDriverCatalogs: readonly CaaraCodexRoleDriverCatalog[] = [
  {
    driverName: "Claude",
    executableName: "claude",
    roles: claudeCodexRoleDefinitions,
  },
  {
    driverName: "Antigravity",
    executableName: "agy",
    roles: antigravityCodexRoleDefinitions,
  },
];

/** All role definitions Caara may manage by generated filename. */
export const allSafeCodexRoleDefinitions: readonly CaaraCodexRoleDefinition[] =
  safeCodexRoleDriverCatalogs.flatMap((catalog) => catalog.roles);
